import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function _test(address v, address u, address vault) internal {
        try c.init(v, u, vault) {} catch { return; }
        assertTrue(c.VADER() == v && c.USDV() == u);
    }

    function testFuzz_test(address v, address u, address vault) public {
        vm.assume(v.code.length == 0 && uint160(v) > 0xffff && v != address(this) && v != address(c) && v != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && v != 0x000000000000000000636F6e736F6c652e6c6f67 && v != 0x4e59b44847b379578588920cA78FbF26c0B4956C && v != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(u.code.length == 0 && uint160(u) > 0xffff && u != address(this) && u != address(c) && u != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && u != 0x000000000000000000636F6e736F6c652e6c6f67 && u != 0x4e59b44847b379578588920cA78FbF26c0B4956C && u != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(vault.code.length == 0 && uint160(vault) > 0xffff && vault != address(this) && vault != address(c) && vault != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && vault != 0x000000000000000000636F6e736F6c652e6c6f67 && vault != 0x4e59b44847b379578588920cA78FbF26c0B4956C && vault != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _test(v, u, vault);
    }

    receive() external payable {}

    fallback() external payable {}
}
